const MODE_INFO={A:['PERFIL C + CONTATO A','Pilotagem terrestre extraída do P01; contato 3D e recuperação aérea experimentais. Valores ambíguos permanecem pendentes.']};
const PV=P08.V;let worldBatches=[],worldLines=null,eventTimes={A:-10,B:-10,C:-10},collisionTimes={A:-10,B:-10,C:-10},lastContacts={A:true,B:true,C:true};
function notify(s,error=false){$('notice').textContent=s;$('notice').style.color=error?'#ff9292':'#69f1dc';}
function download(name,obj){const url=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function rebuildWorld(){
 for(const b of worldBatches)delBuf(b.buf);if(worldLines)delBuf(worldLines.buf);worldBatches=[];
 const groups=new Map();for(const t of course.triangles){const k=t.zone+':'+t.kind;if(!groups.has(k))groups.set(k,[]);groups.get(k).push(t);}
 for(const [key,ts]of groups){const pos=[],norm=[];for(const t of ts)for(const p of [t.a,t.b,t.c]){pos.push(...p);norm.push(...t.n);}const il=interleave([{positions:pos,normals:norm}]);worldBatches.push({buf:mkBuf(il.data),count:il.count,color:key.endsWith('barrier')?[.18,.08,.2]:[.22,.26,.38]});}
 const pos=[],norm=[];for(let i=0;i<course.stations.length-1;i++){const a=course.stations[i],b=course.stations[i+1];if(a.gap||b.gap||PV.len(PV.sub(a.p,b.p))>8)continue;
  if(i%8===0){for(const u of [-1,1]){const A=PV.add(a.p,PV.add(PV.mul(a.r,u*(a.tube>0?12:46)),PV.mul(a.n,.06))),B=PV.add(b.p,PV.add(PV.mul(b.r,u*(b.tube>0?12:46)),PV.mul(b.n,.06)));pos.push(...A,...B);norm.push(...a.n,...b.n);}}
  if(i%24===0&&!a.tube){for(const p of [PV.add(a.p,PV.add(PV.mul(a.r,-44),PV.mul(a.n,.07))),PV.add(a.p,PV.add(PV.mul(a.r,44),PV.mul(a.n,.07)))]){pos.push(...p);norm.push(...a.n);}}
 }
 const il=interleave([{positions:pos,normals:norm}]);worldLines={buf:mkBuf(il.data),count:il.count};
}
function lookLocal(eye,target,up){const z=PV.norm(PV.sub(eye,target)),x=PV.norm(PV.cross(up,z)),y=PV.cross(z,x);return[x[0],y[0],z[0],0,x[1],y[1],z[1],0,x[2],y[2],z[2],0,-PV.dot(x,eye),-PV.dot(y,eye),-PV.dot(z,eye),1];}
function basisMatrix(b){const x=PV.norm(PV.cross(b.up,b.f)),y=b.up,z=b.f;return[x[0],x[1],x[2],0,y[0],y[1],y[2],0,z[0],z[1],z[2],0,...b.p,1];}
function viewFor(b,w,h){const up=b.up,f=b.f,right=PV.norm(PV.cross(up,f));let eye,target=PV.add(b.p,PV.mul(up,1));
 if(config.camera==='side')eye=PV.add(b.p,PV.add(PV.mul(right,30),PV.mul(up,9)));
 else if(config.camera==='rear')eye=PV.add(b.p,PV.add(PV.mul(f,-24),PV.mul(up,4)));
 else if(config.camera==='inspect')eye=PV.add(b.p,PV.add(PV.mul(right,Math.sin(orbitYaw)*Math.cos(orbitPitch)*orbitDistance),PV.add(PV.mul(f,-Math.cos(orbitYaw)*Math.cos(orbitPitch)*orbitDistance),PV.mul(up,Math.sin(orbitPitch)*orbitDistance))));
 else{eye=PV.add(b.p,PV.add(PV.mul(f,-29),PV.mul(up,11)));target=PV.add(b.p,PV.add(PV.mul(f,18),PV.mul(up,2)));}
 return m4.mul([...mat4Persp(62*D2R,w/h,.15,6500)],lookLocal(eye,target,up));
}
function drawWorld(vp){beginCraft(vp);const gl=GLR.gl;gl.uniformMatrix4fv(GLR.u.model,false,new Float32Array(m4.I()));gl.uniformMatrix3fv(GLR.u.rot,false,rotMat3(0));gl.uniform1f(GLR.u.smooth,0);gl.disable(gl.CULL_FACE);gl.depthMask(true);
 for(const b of worldBatches){bindBuf(b);setU({color:b.color,role:0});draw(b,gl.TRIANGLES,true);}bindBuf(worldLines);setU({flat:true,color:[.42,.75,.75],opacity:.8});draw(worldLines,gl.LINES,false);
}
function drawBody(vp,b){const e=prepared(config.ship,config.model),bounds=e.report.bounds,cx=(bounds.min[0]+bounds.max[0])/2,cy=(bounds.min[1]+bounds.max[1])/2,cz=(bounds.min[2]+bounds.max[2])/2,visualRight=PV.norm(PV.cross(b.f,b.up)),visualF=P08.noseDirection(b),visualUp=P08.rotate(P08.rotate(b.up,visualRight,b.driver.pitch),visualF,b.driver.roll),root=basisMatrix({...b,f:visualF,up:PV.norm(PV.cross(PV.cross(visualF,visualUp),visualF))}),model=m4.mul(root,m4.T(-cx,-cy,-cz)),rot=new Float32Array([root[0],root[1],root[2],root[4],root[5],root[6],root[8],root[9],root[10]]);
 beginCraft(vp);renderModel(e,model,rot,resolveLivery('B',config.ship));
 const sim={speed:PV.len(b.v)*3.6,throttle:keysHeld.has('KeyX')||keysHeld.has('KeyW')||scriptMode?1:0,slip:b.slip/60,impact:clamp(b.lastImpact/100,.1,1),gravity:16,height:0};
 arena.reset();ghosts.length=0;effectFrame('propulsion','A',VFX_BASELINE.propulsion.A,b.time,e,sim,1,config.seed);
 if(b.boost>0)effectFrame('boost','B',VFX_BASELINE.boost.B,(2.4-b.boost)%VFX_BASELINE.boost.B.duration,e,sim,1,config.seed);
 if(PV.len(b.v)>200)effectFrame('speed','A',VFX_BASELINE.speed.A,b.time,e,sim,1,config.seed);
 if(b.time-collisionTimes[b.mode]<.65)effectFrame('collision','B',VFX_BASELINE.collision.B,b.time-collisionTimes[b.mode],e,sim,1,config.seed);
 renderArena(vp,model);
 // Technical normal and contact point: diagnostic, deliberately not presented as approved VFX.
 arena.reset();const n=b.normal,base=PV.sub(b.p,PV.mul(n,b.distance??config.profile.hoverHeight));if(b.contact){arena.stroke(base,PV.add(base,PV.mul(n,7)),.08,[.5,1,.72],.8);arena.shard(base,.3,[1,.65,.25],1,0);}renderArena(vp,m4.I());
}
function drawScene08(){if(!GLR.ok||GLR.lost)return;const gl=GLR.gl,dpr=Math.min(devicePixelRatio||1,1.5),w=Math.round(canvas.clientWidth*dpr),h=Math.round(canvas.clientHeight*dpr);if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;}GLR.frame={draws:0,tris:0};diagnostic.fxVertices=0;const modes=comparison?['A']:[config.mode];gl.enable(gl.SCISSOR_TEST);modes.forEach((m,i)=>{const x=Math.floor(i*w/modes.length),ww=Math.floor((i+1)*w/modes.length)-x;gl.viewport(x,0,ww,h);gl.scissor(x,0,ww,h);gl.clearColor(.038,.045,.092,1);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);const vp=viewFor(bodies[m],ww,h);drawWorld(vp);drawBody(vp,bodies[m]);});gl.disable(gl.SCISSOR_TEST);}
let boostQueued=false,inputEdges=[];
function inputNow(){return{keys:[...keysHeld],edges:inputEdges.slice(),boost:boostQueued,release:releaseQueued};}
function oneStep(){const start=performance.now(),input=scriptMode?P08.scripted(bodies.A.time,config.seed):inputNow();for(const m of ['A']){const b=bodies[m],last=b.collisions;P08.step(course,b,config.params[m],input,config.profile,{naturalStability:config.naturalStability,regeneration:config.regeneration,air:config.air});if(b.collisions>last)collisionTimes[m]=b.time;if(b.contact!==lastContacts[m])eventTimes[m]=b.time;lastContacts[m]=b.contact;}releaseQueued=false;boostQueued=false;inputEdges=[];stepMs=performance.now()-start;simSteps++;if(scriptMode&&bodies.A.time>=10){paused=true;scriptMode=false;notify('Ensaio de 10 segundos concluído. Exporte a configuração e a telemetria.');syncUI();}}
function advance(dt){if(!Number.isFinite(dt)||dt<0)throw Error('delta inválido');const accepted=Math.min(dt,.25);droppedTime+=dt-accepted;accumulator+=accepted;while(accumulator+1e-10>=P08.DT){oneStep();accumulator-=P08.DT;if(paused)break;}}
function frame(t){const dt=lastTime?(t-lastTime)/1000:0;lastTime=t;if(!paused&&!document.hidden&&GLR.ok)advance(dt);else accumulator=0;const start=performance.now();drawScene08();renderMs=performance.now()-start;frameCount++;if(t-sampleStart>=700){fps=frameCount*1000/(t-sampleStart);frameCount=0;sampleStart=t;}if(t-lastUi>180){metrics();lastUi=t;}requestAnimationFrame(frame);}
function format(v,d=2){return v===null?'—':typeof v==='number'?v.toFixed(d):String(v);}function vec(v){return v.map(x=>format(x,1)).join(' / ');}
function metrics(){const b=bodies[config.mode],rows=[['Estado',b.event],['Causa',b.reason],['Área',course.zones[b.zone]?.name||'—'],['Tempo / tick',format(b.time)+' / '+b.tick],['Posição XYZ',vec(b.p)],['Velocidade XYZ',vec(b.v)],['Vertical global',format(b.v[1])+' u/s'],['Limite de descida',format(b.diveCap??config.profile.airDiveMaxSpeed)+' u/s'],['Normal local',vec(b.normal)],['Distância',format(b.distance)+' u'],['Suspensão',format(b.suspension,1)+' u/s²'],['Magnetismo',format(b.magnetic,1)+' u/s²'],['Correção A',format(b.correction,4)+' u'],['Slip lateral',format(b.slip)+' u/s'],['Impacto último pouso/contato',format(b.lastImpact)+' u/s'],['Erro orientação',format(b.orientationError)+'°'],['Pousos / desprend.',b.landings+' / '+b.detachments],['Roll / pitch P01',format(b.driver.roll*180/Math.PI)+' / '+format(b.driver.pitch*180/Math.PI)+'°'],['Energia P01',format(b.energy)],['Erro nivelamento aéreo',format(b.levelError||0)+'°'],['Empuxo boost aéreo',format(b.airThrust||0)+' u/s²'],['Bônus último passo',format(b.landingBonus)+' u/s'],['FPS',format(fps,0)],['Física Perfil C + A',format(stepMs)+' ms'],['Render CPU',format(renderMs)+' ms'],['Tempo descartado',format(droppedTime)+' s']];$('metrics').replaceChildren(...rows.map(([a,v])=>{const e=document.createElement('div');e.className='metric';const s=document.createElement('span'),n=document.createElement('b');s.textContent=a;n.textContent=v;e.append(s,n);return e;}));$('speed').textContent=Math.round(PV.len(b.v)*3.6);$('contact').textContent=b.event;$('modeTag').textContent=MODE_INFO[config.mode][0];
 $('compareTable').innerHTML='<tr><th>Agora</th><th>Perfil C + A</th></tr>'+[['Altura u',m=>format(bodies[m].distance)],['Pousos',m=>bodies[m].landings],['Voo s',m=>format(bodies[m].airTime)],['Impacto u/s',m=>format(bodies[m].lastImpact)]].map(([s,f])=>'<tr><th>'+s+'</th>'+['A'].map(m=>'<td>'+f(m)+'</td>').join('')+'</tr>').join('');
 const c=$('graph'),g=c.getContext('2d');g.clearRect(0,0,c.width,c.height);g.strokeStyle='#ffffff66';g.beginPath();g.moveTo(0,160-config.profile.hoverHeight*25);g.lineTo(460,160-config.profile.hoverHeight*25);g.stroke();for(const [i,m]of ['A'].entries()){g.strokeStyle=['#69f1dc','#ff548d','#ffcf7a'][i];g.lineWidth=2;g.beginPath();let pen=false;const arr=bodies[m].trace;for(let j=0;j<arr.length;j++){const h=arr[j].height;if(h===null){pen=false;continue;}const x=j/Math.max(1,arr.length-1)*460,y=160-h*25;if(pen)g.lineTo(x,y);else g.moveTo(x,y);pen=true;}g.stroke();}}
function sliders(){const box=$('sliders');box.replaceChildren();for(const k of P08.ACTIVE[config.mode]){const d=P08.PARAMS[k],row=document.createElement('div');row.className='slider';const lab=document.createElement('label'),title=document.createElement('span'),out=document.createElement('output'),input=document.createElement('input');title.textContent=d[0];input.type='range';input.min=d[1];input.max=d[2];input.step=d[4];input.value=config.params[config.mode][k];input.dataset.param=k;input.setAttribute('aria-label',d[0]);out.textContent=input.value+' '+d[5];lab.append(title,out);input.oninput=()=>{config.params[config.mode][k]=Number(input.value);out.textContent=input.value+' '+d[5];};row.append(lab,input);box.append(row);}}
