function syncUI(){for(const e of document.querySelectorAll('[data-mode]'))e.classList.toggle('on',e.dataset.mode===config.mode);$('modeDescription').textContent=MODE_INFO[config.mode][1];$('compare').classList.toggle('on',comparison);$('hud').hidden=comparison;$('compareLabels').style.display=comparison?'flex':'none';$('compareLabels').innerHTML=['A'].map(m=>'<span>'+MODE_INFO[m][0]+'</span>').join('');$('pause').textContent=paused?'▶ Continuar':'Ⅱ Pausar';for(const k of ['ship','model','zone','camera','seed','startSpeed'])$(k).value=config[k];$('startOut').textContent=config.startSpeed+' u/s · '+config.startSpeed*3.6+' km/h';$('airEnabled').checked=config.air.enabled;$('airHint').textContent=config.air.downToDive?'No ar: ↓/S mergulha; ↑ empina; A/B aplica boost na direção do nariz. Segure ↓/S + boost para descer mais rápido, ou ↑ + boost para frear a queda e subir. W acelera e também mergulha. O fator 1,30× amplia pitch, direção, strafe e limite de descida durante o boost. O boost consome energia.':'Modo importado: ↓/S empina e ↑/W mergulha, como na revisão anterior. A/B aplica boost na direção do nariz. Para mergulhar com boost, use ↑ + A/B.';$('airKeys').textContent=config.air.downToDive?'↓/S + A/B: mergulhar rápido · ↑ + A/B: recuperar altitude · W: acelerar/mergulhar':'↓/S + A/B: recuperar altitude · ↑/W + A/B: mergulhar';sliders();airSliders();metrics();}
