window.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;keysHeld.add(e.code);inputEdges.push(e.code);if(e.code==='KeyR')resetLab();if(e.code==='KeyP'){paused=!paused;syncUI();}if(e.code==='KeyJ')releaseQueued=true;if(e.code==='KeyA'||e.code==='KeyB')boostQueued=true;if(e.code==='KeyV'){const k=['chase','side','rear','inspect'];config.camera=k[(k.indexOf(config.camera)+1)%4];syncUI();}});window.addEventListener('keyup',e=>keysHeld.delete(e.code));window.addEventListener('blur',()=>keysHeld.clear());document.addEventListener('visibilitychange',()=>{keysHeld.clear();accumulator=0;lastTime=0;});
